def icon(name, cls='h-5 w-5', id=None):
    """<svg> for a Material icon name. aria-hidden: every icon here sits
    beside a visible label or inside a control with an aria-label. `id` is
    for the few a script shows and hides (the password eye toggles)."""
    body = ICONS[name]
    id_attr = Markup(' id="%s"') % id if id else Markup('')
    return Markup(
        '<svg%s class="icon %s" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" '
        'fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" '
        'stroke-linejoin="round" aria-hidden="true" focusable="false">%s</svg>'
    ) % (id_attr, escape(cls), Markup(body))
